static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket < 19000101 || timeBucket > 99991231) {
        return timeBucket;
    }
    if (dayStep <= 0) {
        return timeBucket;
    }
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);
    if (month < 1 || month > 12 || day < 1 || day > 31) {
        return timeBucket;
    }
    int validDay = Math.min(day, getDaysInMonth(year, month));
    if (validDay != day) {
        return timeBucket;
    }
    int compressedDay = ((validDay - 1) / dayStep) * dayStep + 1;
    if (compressedDay > validDay) {
        compressedDay = validDay;
    }
    long result = (long) year * 10000 + month * 100 + compressedDay;
    return result;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    // Extract the last 6 digits representing yyyyMMdd
    long datePart = timeBucket % 1000000;
    // Cast to Calendar
    long year = datePart / 10000;
    long month = (datePart / 100) % 100;
    long day = datePart % 100;

    // We need to find the first day of the current month
    long firstDayOfMonth = year * 10000 + month * 100 + 1;

    // days since the beginning of the month, 0-indexed
    long daysSinceBegin = day - 1;

    // Find the start of the current dayStep chunk
    // The dayStep chunks start from day 1.
    // Chunk 0: days 1 to dayStep
    // Chunk 1: days dayStep+1 to 2*dayStep
    // Start day of chunk = (chunk_index * dayStep) + 1
    long chunkIndex = (int) (daysSinceBegin / dayStep);
    long startDay = (chunkIndex * dayStep) + 1;

    // Reconstruct the full time bucket literal
    // The prefix (before date) remains the same
    long prefix = timeBucket - datePart;
    long compressedDate = year * 10000 + month * 100 + startDay;

    return prefix + compressedDate;
}

