    int total = 0;
    LinkedBuffer current = node;
    while (current != null) {
        byte[] data = current.data;
        out.write(data);
        total += data.length;
        current = current.next;
    }
    return total;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }
    int totalWritten = 0;
    LinkedBuffer current = node;
    byte[] currentBytes = current.getBytes();
    while (current != null) {
        if (currentBytes != null) {
            out.write(currentBytes, 0, currentBytes.length);
            totalWritten += currentBytes.length;
        }
        current = current.getNext();
        if (current != null) {
            currentBytes = current.getBytes();
        }
    }
    return totalWritten;
}

