public static int nextPrime(int desiredCapacity) {
    int found = (int) (desiredCapacity * 1.1) + 1;
    for (int test = desiredCapacity | 1; test <= found; test += 2) {
        boolean isPrime = true;
        int limit = (int) Math.sqrt(test);
        for (int i = 3; i <= limit; i += 2) {
            if (test % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return test;
        }
    }
    return desiredCapacity;
}

