private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate,Node start,Node stop,int dir){
        if ( start != stop ) {
            // moving clockwise
            for ( Node v = start.outgoing(dir); v != stop; v = v.nextOutgoing(dir) ) {
                if ( predicate.test(v) ) {
                    return new OuterFaceCirculator(v, opposite(dir));
                }
            }
        }
        return new OuterFaceCirculator(stop, dir);
    }

