public int compare(Object aObj1,Object aObj2){
    byte[] a = (byte[]) aObj1;
    byte[] b = (byte[]) aObj2;

    int len = Math.min(a.length, b.length);
    for (int i = 0; i < len; i++) {
        int cmp = (a[i] << 8) - (b[i] << 8);
        if (cmp != 0) {
            return cmp;
        }
    }
    return a.length - b.length;
}

public int compare(Object aObj1, Object aObj2) {
    if (aObj1 == aObj2) {
        return 0;
    }
    if (aObj1 == null || aObj2 == null) {
        throw new NullPointerException("Cannot compare null values");
    }

    try {
        Comparable c1 = (Comparable) aObj1;
        Comparable c2 = (Comparable) aObj2;
        return c1.compareTo(c2);
    } catch (ClassCastException e) {
        throw new ClassCastException("Objects are not comparable");
    }
}

public int compare(Object aObj1, Object aObj2) {
    try {
        byte[] byte1 = (byte[]) aObj1;
        byte[] byte2 = (byte[]) aObj2;

        int len1 = byte1.length;
        int len2 = byte2.length;

        // Compare common prefix
        int minLength = Math.min(len1, len2);
        for (int i = 0; i < minLength; i++) {
            int cmp = compare(byte1[i], byte2[i]);
            if (cmp != 0) {
                return cmp;
            }
        }

        // If no difference in common prefix, shorter array is lesser
        return (len1 - len2);
    } catch (ClassCastException e) {
        throw e;
    }
}

