protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
 List<E> tourList = new ArrayList<>(tour);
 // start the path at either endpoint of the edge list
 Edge<E,V> e0 = tourList.get(0);
 GraphPath<V,E> p = new DefaultGraphPath<>(graph);
 V lastVertex = e0.getOutVertex();
 p.setStartVertex(lastVertex);
 p.addEdge(e0);
 lastVertex = e0.getInVertex();
 // build the tour by iteratively adding edges
 while(!tourList.isEmpty()){
   Iterator<E> it = tourList.iterator();
   while(it.hasNext()){
     Edge<E,V> e = it.next();
     it.remove(); // remove the edge from our working set
     // the edge must be either (lastVertex, X) or (X, lastVertex)
     V x = e.getOtherVertex(lastVertex);
     if(e.getOutVertex().equals(lastVertex) || e.getInVertex().equals(lastVertex)){
       p.addEdge(e);
       // the direction of the edge determines the new last vertex
       lastVertex = x;
       break;
     }
   }
