protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
GraphPath<V,E> result = new GraphPath<V,E>();
Vertex<V,start>.fill(result.getVertices(),2);
if(tour.size() == 1){
    Edge<E> theEdge = tour.iterator().next();
    result.addVertex(theEdge.getFrom());
    result.addVertex(theEdge.getTo());
    result.addEdge(theEdge);
}
else{
    E edge = tour.iterator().next();
    tour.remove(edge);
    result.addVertex(edge.getFrom());
    result.addEdge(edge);
    if(edge.getFrom().equals(edge.getTo())){
        // self-loop
        result.addVertex(edge.getFrom());
    }
    else{
        result.addVertex(edge.getTo());
    }
    while(tour.size()> 0){
        LiteIterator<Edge<E>> edgeList = Utils.iterator(tour.iterator());
        Iterator<Edge<E>> iterator = edgeList.iterator();
        while(iterator.hasNext()){
            // first edge reversing
            Edge<E> currentEdge = iterator.next();
            if(currentEdge.getFrom().equals(result.getVertex(result.size()-1))){
                // adding edge following to last
                result.addVertex(currentEdge.getTo());
                result.addEdge(currentEdge);
                tour.remove(currentEdge);
                break;
            }
            else if(currentEdge.getTo().equals(result.getVertex(result.size()-1))){
                // adding edge reversing to last
                Edge<E> reverseEdge = currentEdge.reverse();
                result.addVertex(currentEdge.getFrom());
                result.addEdge(reverseEdge);
                tour.remove(currentEdge);
                break;
            }
        }
    }
}
return result;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
	/**
	 * Try to build a Path from the Set of Edges
	 */
	if (tour.isEmpty()) {
		return null;
	}
	Map<V, List<E>> edgeKeyedByStart = groupEdges(tour, graph);
	//let's try to build the path.
	//since we do know it's a simpletour
	//there should be only one edge going out from each vertex
	//if the graph is directed only one edge should enter a vertex
	TreeMap<V, List<E>> staticMap = new TreeMap<>(edgeKeyedByStart);
	//only the start will be on one end
	V startPoint = (staticMap.get(staticMap.firstKey()).size() == 1) ? staticMap.firstKey() : null;
	if (graph.isDirected()) {
		//it is directed so let's filter out all vertices with two outgoing edges
		staticMap = edgeKeyedByStart.entrySet().stream().filter(x -> x.getValue().size() == 1)
				.collect(Collectors.toMap(Entry::getKey, Entry::getValue, (e1, e2) -> e1, TreeMap::new));
	}
	if (staticMap.isEmpty()) {
		//if we could not determine a start, then the Tour is not valid
		return null;
	}
	//grab the starting point
	startPoint = staticMap.keySet().iterator().next();
	//try to find the end first
	//the end is the other end of an edge, which is not a key, or has two edges
	//it does not exist in the staticMap
	V endPoint = null;
	for (Entry<V, List<E>> entry : staticMap.entrySet()) {
		E edge = entry.getValue().get(0);
		V otherEnd = edge.getOtherVertex(entry.getKey());
		if (!staticMap.containsKey(otherEnd) || staticMap.get(otherEnd).size() == 2) {
			//this is the end point
			endPoint = otherEnd;
			break;
		}
	}
	if (endPoint == null) {
		//could not find the end, thus not a valid tour
		return null;
	}
	//now let's build the path
	//assume it's a simple tour
	List<E> tourPath = new ArrayList<>();
	V current = startPoint;
	V next = null;
	//while we don't get to the end
	while (!Objects.equals(current, endPoint)) {
		//find the next edge
		List<E> edges = staticMap.get(current);
		if (edges == null || edges.isEmpty()) {
			//we don't have an edge leaving this point, thus it's broken
			return null;
		}
		E currentEdge = edges.get(0);
		tourPath.add(currentEdge);
		//we can't have a loop in a simple tour
		if (Objects.equals(currentEdge.getFromVertex(), currentEdge.getToVertex())) {
			return null;
		}
		//move to next point
		next = currentEdge.getOtherVertex(current);
		//add this visited edge as used, since we could have a multigraph
		//which we don't deal with here
		staticMap.get(current).remove(currentEdge);
		//update current
		current = next;
		//don't go in circles
		if (tourPath.size() > tour.size()) {
			return null;
		}
	}
	//extend to a path
	return new DirectedLexicographicPath<>(tourPath.concat());
}

