private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    char[] chars = input.toCharArray();
    for (int i = 0; i < chars.length; i++) {
        char c = chars[i];
        if (c == '\'') {
            // Skip the quote and handle the next character
            if (i + 1 < chars.length) {
                char next = chars[i + 1];
                if (next == '\\') {
                    // Escaped quote: consumes the backslash, adds a single quote
                    sb.append('\'');
                    i++; // Skip the backslash
                } else if (next == '\'') {
                    // Quoted quote: consumes the second quote, adds a single quote
                    sb.append('\'');
                    i++;
                } else {
                    // Shouldn't happen in valid input, but just in case, append the quote
                    sb.append(c);
                }
            } else {
                // Trailing quote
                sb.append(c);
            }
        } else if (c == '\\' && i + 1 < chars.length) {
            // Backslash must escape the next character
            char next = chars[i + 1];
            sb.append(next);
            i++; // Skip the next character as it is already consumed
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < input.length()) {
            char next = input.charAt(i + 1);
            if ((next >= 'a' && next <= 'z') || (next >= 'A' && next <= 'Z') || (next >= '0' && next <= '9') || next == '_') {
                sb.append(next);
                i++;
            } else if (next == 'n') {
                sb.append('\n');
                i++;
            } else if (next == 't') {
                sb.append('\t');
                i++;
            } else {
                sb.append(c);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    if (input.length() < 2) {
        return input;
    }
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '"' && i > 0 && input.charAt(i - 1) == '\\') {
            i++;
            if (i < input.length()) {
                char next = input.charAt(i);
                switch (next) {
                    case 'n':
                        result.append('\n');
                        break;
                    case 't':
                        result.append('\t');
                        break;
                    case 'r':
                        result.append('\r');
                        break;
                    case '\\' :
                        result.append('\\');
                        break;
                    case '"':
                        result.append('"');
                        break;
                    default:
                        result.append(c).append(next);
                }
            } else {
                result.append(c);
            }
        } else {
            result.append(c);
        }
    }
    return result.toString();
}

