private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
        Set<Integer> bucketToMove = bucketsByLabel.get(minLabel);
        Set<Integer> bucketZero = bucketsByLabel.get(0);
        for (Integer vertex : bucketToMove) {
            Integer label = labels.get(vertex);
            bucketsByLabel.get(label).remove(vertex); // Remove from its current bucket (which is minLabel)
            bucketZero.add(vertex); // Add to the zero bucket
            labels.set(vertex, 0); // Update the label to 0
        }
        bucketToMove.clear(); // Clear the minLabel bucket (it's now empty since we moved all its elements)
    }

