public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        return Unknown.class;
    }
    Type[] bounds = typeVariable.getBounds();
    if (bounds == null || bounds.length == 0) {
        return Unknown.class;
    }
    Type firstBound = bounds[0];
    if (firstBound instanceof Class) {
        return firstBound;
    }
    if (firstBound instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) firstBound;
        return parameterizedType.getRawType();
    }
    if (firstBound instanceof WildcardType) {
        WildcardType wildcardType = (WildcardType) firstBound;
        Type[] upperBounds = wildcardType.getUpperBounds();
        if (upperBounds != null && upperBounds.length > 0) {
            return resolveBound((TypeVariable<?>) upperBounds[0]);
        }
        return Unknown.class;
    }
    if (firstBound instanceof GenericArrayType) {
        GenericArrayType genericArrayType = (GenericArrayType) firstBound;
        return resolveBound((TypeVariable<?>) genericArrayType.getGenericComponentType());
    }
    return Unknown.class;
}

