    // but per the standard "apply" semantics, we generally want to resolve the relative path against the base path.
    // The description says "Apply the given relative path to the given path".
    // Example: path = "/a/b", relativePath = "../c" -> "/a/c"
    // Example: path = "/a/b", relativePath = "c" -> "/a/b/c"

    // Let's break down the base path into parts
    boolean isRoot = normalizedPath.startsWith("/");
    String[] baseParts;
    if (isRoot) {
        // If it starts with /, the first element of split will be ""
        baseParts = normalizedPath.split("/");
        // Filter out empty strings to get actual directory names
        List<String> parts = new ArrayList<>();
        for (String part : baseParts) {
            if (!part.isEmpty()) {
                parts.add(part);
            }
        }
        // Convert list to array
        baseParts = parts.toArray(new String[0]);
    } else {
        baseParts = normalizedPath.split("/");
        List<String> parts = new ArrayList<>();
        for (String part : baseParts) {
            if (!part.isEmpty()) {
                parts.add(part);
            }
        }
        baseParts = parts.toArray(new String[0]);
    }

    List<String> finalParts = new ArrayList<>();

    for (String part : baseParts) {
        if (part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!finalParts.isEmpty()) {
                finalParts.remove(finalParts.size() - 1);
            }
        } else {
            finalParts.add(part);
        }
    }

    for (String part : relativeParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!finalParts.isEmpty()) {
                finalParts.remove(finalParts.size() - 1);
            }
        } else {
            finalParts.add(part);
        }
    }

    String result = String.join("/", finalParts);

    if (isRoot) {
        result = "/" + result;
        // Ensure we don't end up with "///" if result is empty
        if (result.length() > 1 && result.endsWith("/")) {
             // This logic is already handled by join which doesn't add trailing slash unless empty part added? 
             // String.join doesn't add trailing separator. 
             // However, if the path was "/a/b/", normalized to "a,b", result "a/b", final "/a/b".
             // If the input path was "/", baseParts is empty.
             // If relative path is "", handled above.
             // If input is "/", result is "". return "/".
        }
    }

    return result;
}

