public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }

    // Normalize the separator to '/' for easier processing
    String normalizedPath = path.replace('\\', '/');
    String normalizedRelativePath = relativePath.replace('\\', '/');

    // Remove trailing slash from normalizedPath to avoid issues
    while (normalizedPath.endsWith("/")) {
        normalizedPath = normalizedPath.substring(0, normalizedPath.length() - 1);
    }

    // If relativePath is empty, return the original path
    if (normalizedRelativePath.isEmpty()) {
        return path;
    }

    // Split the relative path into components
    String[] relativeParts = normalizedRelativePath.split("/");

    StringBuilder result = new StringBuilder(normalizedPath);

    for (String part : relativeParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            // Remove the last directory component
            int lastSlash = result.lastIndexOf('/');
            if (lastSlash > 0) {
                result.setLength(lastSlash);
            } else if (lastSlash == 0) {
                // We are at the root, so remove everything
                result.setLength(0);
            } else {
                // No more directories to remove, ignore
            }
        } else {
            result.append('/').append(part);
        }
    }

    return result.toString();
}

