static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    if (array.length == 0) {
        return new String[0];
    }
    // First pass: check if there are any nulls
    boolean hasNull = false;
    for (Object obj : array) {
        if (obj == null) {
            hasNull = true;
            break;
        }
    }
    if (!hasNull) {
        // If no nulls, we can return a copy or the same type if it's already String[]
        // But the signature says String[], so if input is Object[], we might need to convert.
        // However, usually these utilities assume the array elements are Strings or compatible.
        // Let's just create a new String array of the same size and copy.
        String[] result = new String[array.length];
        for (int i = 0; i < array.length; i++) {
            result[i] = (String) array[i];
        }
        return result;
    } else {
        // Second pass: create a new array without nulls
        int count = 0;
        for (Object obj : array) {
            if (obj != null) {
                count++;
            }
        }
        String[] result = new String[count];
        int index = 0;
        for (Object obj : array) {
            if (obj != null) {
                result[index++] = (String) obj;
            }
        }
        return result;
    }
}

